CREATE FUNCTION IF NOT EXISTS "EXTRACT_RELEVANT_MENU_FIELDS"("PRODUCT_STR" VARCHAR(16777216))
RETURNS ARRAY
LANGUAGE PYTHON
RUNTIME_VERSION = '3.8'
HANDLER = 'extract_fields'
AS '
def extract_fields(product_str):
    import json
    products_json = json.loads(product_str)
    prod_ids = products_json.keys()

    out_array = []

    for id in prod_ids:
        name = products_json[id][''name'']
        item_type = products_json[id][''type'']

        for item in products_json[id][''items''].keys():

            out_obj = {
              ''parent_id'': id,
              ''name'': name,
                ''type'': item_type,
                ''items_id'': products_json[id][''items''][item][''id''],
                ''items_name'': products_json[id][''items''][item][''name''],
                ''items_metadata_SOURCE_PRODUCT_ID'': products_json[id][''items''][item][''metadata''][''SOURCE_PRODUCT_ID''],
                ''items_price_currentPrice'': products_json[id][''items''][item][''price''][''currentPrice'']
            }
            
            if products_json[id][''items''][item][''price''].get(''metadata''):
                out_obj[''items_price_metadata_SOURCE_PRODUCT_ID''] = products_json[id][''items''][item][''price''][''metadata''][''SOURCE_PRODUCT_ID'']

            if products_json[id][''items''][item][''price''].get(''otherPrices''):
                out_obj[''items_price_otherPrices_Meal_price''] = products_json[id][''items''][item][''price''][''otherPrices''][''MEAL''][''price'']

            out_array.append(out_obj)
    return out_array
';
CREATE FUNCTION IF NOT EXISTS "FLAT_GA_EVENTS_UP_EP_VALUE"("A" ARRAY)
RETURNS ARRAY
LANGUAGE JAVASCRIPT
AS '
    const FLEXIBLE_KEY_NAMES = ["string_value", "int_value", "double_value", "float_value"]

    const parseInput = (input = {}) => {
        const res = {
            "key": input.key
        };
        const value = input.value;
        if (value) {
            for (const [key, value] of Object.entries(input.value)) {
                if (FLEXIBLE_KEY_NAMES.includes(key)) {
                    res.value = value;
                } else {
                    res[key] = value;
                }
            }
        }
        return res;
    }

    return A.map(parseInput)
  ';
CREATE FUNCTION IF NOT EXISTS "KV_ARRAY_TO_OBJECT"("A" ARRAY)
RETURNS OBJECT
LANGUAGE JAVASCRIPT
AS '
    let dict = {};
    A.forEach(item => {
        dict[item.key] = item.value;
    });
    return dict;
';
