CREATE PROCEDURE IF NOT EXISTS "CUSTOMER_STATUS_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var insert_stream_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."customer_status"(
                                "MEMBER_ID", 
"BRAND_ID", 
"CUSTOMER_STATUS_EFFECTIVE_DATE", 
"CUSTOMER_STATUS_EXPIRY_DATE", 
"CUSTOMER_STATUS_CODE", 
"SOURCE_SYSTEM_NAME", 
"LOAD_TYPE", 
"LOAD_ID", 
"LOAD_DTTM", 
"UPDATE_ID", 
"UPDATE_DTTM", 
"FILENAME"
                              )
                          SELECT
                                delta_stream."MEMBER_ID", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.BRAND_ID), ''__HIVE_DEFAULT_PARTITION__''), 
delta_stream."CUSTOMER_STATUS_EFFECTIVE_DATE", 
delta_stream."CUSTOMER_STATUS_EXPIRY_DATE", 
