delta_table."FILENAME"
                          FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.cust_enriched_plr_delta delta_table
                          WHERE EXISTS(
                                      select
                                          metadata.add_file
                                       from
                                          (
                                             select
                                                metadata_json.add_file
                                             from
                                                (
                                                   select
                                                      add_file
                                                   from `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.cust_enriched_plr_delta_log
                                                   where
                                                      filename >= :1
                                                      and add_file is not null
                                                )
                                                metadata_json
                                             where
                                                not exists
                                                (
                                                   select
                                                      target_table.filename
                                                   from `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."cust_enriched_plr" target_table
                                                   where
                                                      target_table.filename = metadata_json.add_file
                                                )
                                          )
                                          metadata
                                       where
                                          metadata.add_file = delta_table.filename )`;

    var delete_json_data = `DELETE FROM `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."cust_enriched_plr" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.cust_enriched_plr_delta_log
                                        WHERE
                                            remove_file IS NOT NULL and filename >= :1
                            )`;
    var max_checkpoint_log = select_max_checkpoint_log_stmt.execute();
    max_checkpoint_log.next();
    var max_checkpoint_log_value = max_checkpoint_log.getColumnValue(1);

    var min_json_log_value;
    var max_checkpoint_log_to_json_value;
    var multiple_max_checkpoints_search;

    if (max_checkpoint_log_value === null) {
        var min_json_log = select_min_json_log_stmt.execute();
        min_json_log.next();
        min_json_log_value = min_json_log.getColumnValue(1);
    } else {
        var index_of_checkpoint = max_checkpoint_log_value.lastIndexOf(''checkpoint'');
        var multiple_max_checkpoints = max_checkpoint_log_value.slice(0, index_of_checkpoint + 10);
        max_checkpoint_log_to_json_value = multiple_max_checkpoints.replace(''.checkpoint'', ''.json'');
        multiple_max_checkpoints_search = multiple_max_checkpoints + ''%'';
    }

    var json_search = max_checkpoint_log_value !== null ? max_checkpoint_log_to_json_value: min_json_log_value;
    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );
        if (max_checkpoint_log_value !== null) {
        var insert_checkpoint_stmt = snowflake.createStatement(
                {
                sqlText: insert_checkpoint_data,
                binds: [multiple_max_checkpoints_search]
                }
        );
        insert_checkpoint_stmt.execute();
       var delete_checkpoint_data_stmt = snowflake.createStatement(
                {
                sqlText: delete_checkpoint_data,
                binds: [multiple_max_checkpoints_search]
                }
        );
        delete_checkpoint_data_stmt.execute();
        
        }

        var insert_json_data_stmt = snowflake.createStatement(
                {
                sqlText: insert_json_data,
                binds: [json_search]
                }
        );
        insert_json_data_stmt.execute();
        var delete_json_data_stmt = snowflake.createStatement(
                {
                sqlText: delete_json_data,
                binds: [json_search]
                }
        );
        delete_json_data_stmt.execute();
        snowflake.execute (
            {sqlText: "commit"}
        );
        return "Succeeded.";
        }
    catch (err)  {
        snowflake.execute (
            {sqlText: "rollback"}
        );
        throw err;
        }
    ';
CREATE PROCEDURE IF NOT EXISTS "CUST_HOUSEHOLD_PLR_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var insert_stream_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."cust_household_plr"(
                                "MEMBERID", 
"HOUSEHOLDID", 
"ADDRESSLINE1", 
"ADDRESSLINE2", 
"CITY", 
"STATE", 
