CREATE PROCEDURE IF NOT EXISTS "EXT_COVIDMOBILITY_PLR_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var insert_stream_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."ext_covidmobility_plr"(
                                "COUNTRYREGIONCODE", 
"COUNTRYREGION", 
"SUBREGION1", 
