"CDMUPDATEDATE", 
"FILENAME"
                              )
                          SELECT
                                delta_stream."COUNTRYREGIONCODE", 
delta_stream."COUNTRYREGION", 
delta_stream."SUBREGION1", 
delta_stream."SUBREGION2", 
delta_stream."METROAREA", 
delta_stream."ISO31662CODE", 
delta_stream."CENSUSFIPSCODE", 
delta_stream."PLACEID", 
delta_stream."DATE", 
delta_stream."RETAILANDRECREATIONPERCENTCHANGEFROMBASELINE", 
delta_stream."GROCERYANDPHARMACYPERCENTCHANGEFROMBASELINE", 
delta_stream."PARKSPERCENTCHANGEFROMBASELINE", 
delta_stream."TRANSITSTATIONSPERCENTCHANGEFROMBASELINE", 
delta_stream."WORKPLACESPERCENTCHANGEFROMBASELINE", 
delta_stream."RESIDENTIALPERCENTCHANGEFROMBASELINE", 
delta_stream."BRANDID", 
delta_stream."SOURCE", 
delta_stream."CDMLOADDATE", 
delta_stream."CDMUPDATEDATE", 
delta_stream."FILENAME"
                          FROM `
                              + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_covidmobility_plr_delta_stream delta_stream
                          WHERE EXISTS(
                                        select
                                           stream_add.add_file
                                        from
                                           (
                                              select
                                                 log_stream.add_file    
                                              from `
                                                 + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_covidmobility_plr_delta_log_insert_stream log_stream 
                                              where log_stream.add_file is not null 
                                                  and not exists (
                                                                  select 
                                                                     distinct filename 
                                                                  from `
                                                                     + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."ext_covidmobility_plr" target 
                                                                  where 
                                                                      target.filename = log_stream.add_file
                                                  ) 
                                            ) stream_add 
                                         where        
                                             stream_add.add_file = delta_stream.filename )`;

    var delete_json_data = `DELETE FROM ` + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."ext_covidmobility_plr" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `
                                            + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_covidmobility_plr_delta_log
                                        WHERE
                                            remove_file IS NOT NULL
                            )`;
    try {
