CREATE PROCEDURE IF NOT EXISTS "EXT_WEATHER_FORECAST_PLR_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var insert_stream_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."ext_weather_forecast_plr"(
                                "DT", 
"DTISO", 
"CITYID", 
"CITYNAME", 
"LAT", 
"LON", 
"COUNTRY", 
"TIMEZONE", 
"TEMPDAY", 
"TEMPMIN", 
"TEMPMAX", 
"TEMPNIGHT", 
"TEMPEVE", 
"TEMPMORN", 
"FEELSLIKEDAY", 
"FEELSLIKENIGHT", 
"FEELSLIKEEVE", 
"FEELSLIKEMORN", 
"PRESSURE", 
"HUMIDITY", 
"WEATHERID", 
"WEATHERMAIN", 
"WEATHERDESCRIPTION", 
"WEATHERICON", 
"WINDSPEED", 
"WINDDEG", 
"CLOUDS", 
"RAIN", 
"SNOW", 
"RESPONSELAT", 
"RESPONSELON", 
"BRANDID", 
"SOURCE", 
"CDMLOADDATE", 
"LOADTYPE", 
"FILENAME"
                              )
                          SELECT
                                delta_stream."DT", 
delta_stream."DTISO", 
delta_stream."CITYID", 
delta_stream."CITYNAME", 
delta_stream."LAT", 
delta_stream."LON", 
delta_stream."COUNTRY", 
delta_stream."TIMEZONE", 
delta_stream."TEMPDAY", 
delta_stream."TEMPMIN", 
delta_stream."TEMPMAX", 
delta_stream."TEMPNIGHT", 
delta_stream."TEMPEVE", 
delta_stream."TEMPMORN", 
delta_stream."FEELSLIKEDAY", 
delta_stream."FEELSLIKENIGHT", 
delta_stream."FEELSLIKEEVE", 
delta_stream."FEELSLIKEMORN", 
delta_stream."PRESSURE", 
delta_stream."HUMIDITY", 
delta_stream."WEATHERID", 
delta_stream."WEATHERMAIN", 
delta_stream."WEATHERDESCRIPTION", 
delta_stream."WEATHERICON", 
delta_stream."WINDSPEED", 
delta_stream."WINDDEG", 
delta_stream."CLOUDS", 
delta_stream."RAIN", 
delta_stream."SNOW", 
delta_stream."RESPONSELAT", 
delta_stream."RESPONSELON", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.BRANDID), ''__HIVE_DEFAULT_PARTITION__''), 
delta_stream."SOURCE", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.CDMLOADDATE), ''__HIVE_DEFAULT_PARTITION__''), 
delta_stream."LOADTYPE", 
delta_stream."FILENAME"
                          FROM `
                              + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_weather_forecast_plr_delta_stream delta_stream
                          WHERE EXISTS(
                                        select
                                           stream_add.add_file
                                        from
                                           (
                                              select
                                                 log_stream.add_file    
                                              from `
                                                 + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_weather_forecast_plr_delta_log_insert_stream log_stream 
                                              where log_stream.add_file is not null 
                                                  and not exists (
                                                                  select 
                                                                     distinct filename 
                                                                  from `
                                                                     + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."ext_weather_forecast_plr" target 
                                                                  where 
                                                                      target.filename = log_stream.add_file
                                                  ) 
                                            ) stream_add 
                                         where        
                                             stream_add.add_file = delta_stream.filename )`;

    var delete_json_data = `DELETE FROM ` + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."ext_weather_forecast_plr" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `
                                            + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.ext_weather_forecast_plr_delta_log
                                        WHERE
                                            remove_file IS NOT NULL
                            )`;
    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );

        var insert_stream_data_stmt = snowflake.createStatement(
                {
                sqlText: insert_stream_data
                }
        );
        insert_stream_data_stmt.execute();
        var delete_json_data_stmt = snowflake.createStatement(
                {
                sqlText: delete_json_data
                }
        );
        delete_json_data_stmt.execute();
        snowflake.execute (
            {sqlText: "commit"}
        );
        return "Succeeded.";
        }
    catch (err)  {
        snowflake.execute (
            {sqlText: "rollback"}
        );
        throw err;
        }
    ';
