RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '

    var select_max_checkpoint_log_stmt = snowflake.createStatement(
        {
            sqlText: `SELECT max(filename) FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log_parquet`
        });
    var select_min_json_log_stmt = snowflake.createStatement(
        {
            sqlText: `SELECT min(filename) FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log`
        });
    var insert_checkpoint_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."loc_dma_plr"(
"DMACODE", 
"DMASOURCENAME", 
"DMANAME", 
"BRANDID", 
"SOURCE", 
"CDMLOADDATE", 
"FILENAME"

                              )
                          SELECT
                                delta_table."DMACODE", 
delta_table."DMASOURCENAME", 
delta_table."DMANAME", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_table.BRANDID), ''__HIVE_DEFAULT_PARTITION__''), 
delta_table."SOURCE", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_table.CDMLOADDATE), ''__HIVE_DEFAULT_PARTITION__''), 
delta_table."FILENAME"
                          FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta delta_table
                          WHERE EXISTS(
                                       select
                                          metadata.add_file
                                       from
                                          (
                                           select
                                              add_file
                                           from `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log_parquet
                                           where
                                              filename like :1
                                              and add_file is not null
                                          )
                                          metadata
                                       where
                                          metadata.add_file = delta_table.filename )`;

    var delete_checkpoint_data = `DELETE FROM `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."loc_dma_plr" target
                                    WHERE filename in (
                                                SELECT
                                                    remove_file
                                                FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log_parquet delta_log_parquet
                                                WHERE
                                                    delta_log_parquet.remove_file IS NOT NULL and delta_log_parquet.filename like :1
                                    )`;

    var insert_json_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."loc_dma_plr"(
"DMACODE", 
"DMASOURCENAME", 
"DMANAME", 
"BRANDID", 
"SOURCE", 
"CDMLOADDATE", 
"FILENAME"
                              )
                          SELECT
                                delta_table."DMACODE", 
delta_table."DMASOURCENAME", 
delta_table."DMANAME", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_table.BRANDID), ''__HIVE_DEFAULT_PARTITION__''), 
delta_table."SOURCE", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_table.CDMLOADDATE), ''__HIVE_DEFAULT_PARTITION__''), 
delta_table."FILENAME"
                          FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta delta_table
                          WHERE EXISTS(
                                      select
                                          metadata.add_file
                                       from
                                          (
                                             select
                                                metadata_json.add_file
                                             from
                                                (
                                                   select
                                                      add_file
                                                   from `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log
                                                   where
                                                      filename >= :1
                                                      and add_file is not null
                                                )
                                                metadata_json
                                             where
                                                not exists
                                                (
                                                   select
                                                      target_table.filename
                                                   from `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."loc_dma_plr" target_table
                                                   where
                                                      target_table.filename = metadata_json.add_file
                                                )
                                          )
                                          metadata
                                       where
                                          metadata.add_file = delta_table.filename )`;

    var delete_json_data = `DELETE FROM `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."loc_dma_plr" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.loc_dma_plr_delta_log
                                        WHERE
                                            remove_file IS NOT NULL and filename >= :1
                            )`;
    var max_checkpoint_log = select_max_checkpoint_log_stmt.execute();
    max_checkpoint_log.next();
    var max_checkpoint_log_value = max_checkpoint_log.getColumnValue(1);

    var min_json_log_value;
    var max_checkpoint_log_to_json_value;
    var multiple_max_checkpoints_search;

