        min_json_log_value = min_json_log.getColumnValue(1);
    } else {
        var index_of_checkpoint = max_checkpoint_log_value.lastIndexOf(''checkpoint'');
        var multiple_max_checkpoints = max_checkpoint_log_value.slice(0, index_of_checkpoint + 10);
        max_checkpoint_log_to_json_value = multiple_max_checkpoints.replace(''.checkpoint'', ''.json'');
        multiple_max_checkpoints_search = multiple_max_checkpoints + ''%'';
    }

    var json_search = max_checkpoint_log_value !== null ? max_checkpoint_log_to_json_value: min_json_log_value;
    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );
        if (max_checkpoint_log_value !== null) {
        var insert_checkpoint_stmt = snowflake.createStatement(
