            sqlText: `SELECT min(filename) FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.media_promotion_plr_delta_log`
        });
    var insert_checkpoint_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."media_promotion_plr"(
