"SOURCE", 
"BRANDID", 
"CDMLOADDATE", 
"FILENAME"

                              )
                          SELECT
                                delta_table."PROMO_ID1", 
delta_table."PROMO_DES1", 
delta_table."PROMO_ABR1", 
delta_table."PRODUCT_ID", 
delta_table."KEY_PRODUCT", 
delta_table."CURRENT_PROMO", 
delta_table."PROMO_PRICE", 
delta_table."SORT_ORDER", 
delta_table."PRICE_LEVEL", 
delta_table."SOURCE", 
delta_table."BRANDID", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_table.CDMLOADDATE), ''__HIVE_DEFAULT_PARTITION__''), 
delta_table."FILENAME"
                          FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.media_promotion_plr_delta delta_table
                          WHERE EXISTS(
                                       select
                                          metadata.add_file
                                       from
                                          (
                                           select
                                              add_file
                                           from `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.media_promotion_plr_delta_log_parquet
                                           where
                                              filename like :1
                                              and add_file is not null
                                          )
                                          metadata
                                       where
                                          metadata.add_file = delta_table.filename )`;

    var delete_checkpoint_data = `DELETE FROM `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."media_promotion_plr" target
                                    WHERE filename in (
                                                SELECT
                                                    remove_file
                                                FROM `+ SRC_DB_PARAM +`.`+SRC_SCHEMA_PARAM+`.media_promotion_plr_delta_log_parquet delta_log_parquet
                                                WHERE
                                                    delta_log_parquet.remove_file IS NOT NULL and delta_log_parquet.filename like :1
                                    )`;

    var insert_json_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."media_promotion_plr"(
"PROMO_ID1", 
"PROMO_DES1", 
"PROMO_ABR1", 
"PRODUCT_ID", 
"KEY_PRODUCT", 
"CURRENT_PROMO", 
"PROMO_PRICE", 
"SORT_ORDER", 
