CREATE PROCEDURE IF NOT EXISTS "MENU_PRODUCT_PLR_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
