nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.BRAND_ID), ''__HIVE_DEFAULT_PARTITION__''), 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.SOURCE_SYSTEM_NM), ''__HIVE_DEFAULT_PARTITION__''), 
delta_stream."LOAD_TYP", 
delta_stream."LOAD_ID", 
delta_stream."LOAD_DTTM", 
delta_stream."UPDATE_ID", 
delta_stream."UPDATE_DTTM", 
delta_stream."FILENAME"
                          FROM `
                              + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.order_line_delta_stream delta_stream
                          WHERE EXISTS(
                                        select
                                           stream_add.add_file
                                        from
                                           (
                                              select
                                                 log_stream.add_file    
                                              from `
                                                 + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.order_line_delta_log_insert_stream log_stream 
                                              where log_stream.add_file is not null 
                                                  and not exists (
                                                                  select 
                                                                     distinct filename 
                                                                  from `
                                                                     + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."order_line" target 
                                                                  where 
                                                                      target.filename = log_stream.add_file
                                                  ) 
                                            ) stream_add 
                                         where        
                                             stream_add.add_file = delta_stream.filename )`;

    var delete_json_data = `DELETE FROM ` + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."order_line" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `
                                            + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.order_line_delta_log
                                        WHERE
                                            remove_file IS NOT NULL
                            )`;
    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );

        var insert_stream_data_stmt = snowflake.createStatement(
                {
                sqlText: insert_stream_data
                }
        );
        insert_stream_data_stmt.execute();
        var delete_json_data_stmt = snowflake.createStatement(
                {
                sqlText: delete_json_data
                }
        );
        delete_json_data_stmt.execute();
        snowflake.execute (
            {sqlText: "commit"}
        );
        return "Succeeded.";
        }
    catch (err)  {
        snowflake.execute (
            {sqlText: "rollback"}
        );
        throw err;
        }
    ';
