CREATE PROCEDURE IF NOT EXISTS "TEST_RW_020620221_DELTA_STP_PROC_CDM_TO_SNOWFLAKE_SCHEMA_EVOLUTION"()
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var alterTable = "alter table STG_DEV.CDMSYNC.test_rw_020620221_delta add column text3 string as (value:text3::string);";
    var alterExternalTableArray = alterTable.split(";")
    
    var filteredAlterExternalTableArray = alterExternalTableArray.filter(function (el) {
      return el != "";
    });

    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );
        
        for (const alterStmt of filteredAlterExternalTableArray) {
           var alterTableStmt = snowflake.createStatement(
                {
                sqlText: alterStmt
                }
           );
           alterTableStmt.execute();
       }

        snowflake.execute (
            {sqlText: "commit"}
        );
        return "Succeeded.";
        }
    catch (err)  {
        snowflake.execute (
            {sqlText: "rollback"}
        );
        throw err;
        }
    ';
