CREATE PROCEDURE IF NOT EXISTS "TRG_MKTG_ACTIVITY_PLR_STP_PROC_CDM_TO_SNOWFLAKE_TABLES_DELTA"("SRC_DB_PARAM" VARCHAR(16777216), "SRC_SCHEMA_PARAM" VARCHAR(16777216), "DST_DB_PARAM" VARCHAR(16777216), "DST_SCHEMA_PARAM" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var insert_stream_data = `INSERT INTO `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."trg_mktg_activity_plr"(
                                "MEMBERID", 
"MEMBERCARDNUMBER", 
"POINTS", 
"CREATEDDATE", 
"ACTIVITYTYPEDESCRIPTION", 
"STORELOCATION", 
"TRANSACTIONNUMBER", 
"TRANSACTIONID", 
"POINTACTIVITYID", 
"CERTIFICATENUMBER", 
"ACTIVITYTYPEGROUP", 
"ACTIVITYTYPE", 
"PRIVACY", 
"BRANDID", 
"CDMLOADDATE", 
"LOADEDDATE", 
"MODIFIEDDATE", 
"SOURCE", 
"FILENAME"
                              )
                          SELECT
                                delta_stream."MEMBERID", 
delta_stream."MEMBERCARDNUMBER", 
delta_stream."POINTS", 
delta_stream."CREATEDDATE", 
delta_stream."ACTIVITYTYPEDESCRIPTION", 
delta_stream."STORELOCATION", 
delta_stream."TRANSACTIONNUMBER", 
delta_stream."TRANSACTIONID", 
delta_stream."POINTACTIVITYID", 
delta_stream."CERTIFICATENUMBER", 
delta_stream."ACTIVITYTYPEGROUP", 
delta_stream."ACTIVITYTYPE", 
delta_stream."PRIVACY", 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.BRANDID), ''__HIVE_DEFAULT_PARTITION__''), 
nullif(STG_DEV.CDMSYNC.decode_partition(delta_stream.CDMLOADDATE), ''__HIVE_DEFAULT_PARTITION__''), 
delta_stream."LOADEDDATE", 
delta_stream."MODIFIEDDATE", 
delta_stream."SOURCE", 
delta_stream."FILENAME"
                          FROM `
                              + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.trg_mktg_activity_plr_delta_stream delta_stream
                          WHERE EXISTS(
                                        select
                                           stream_add.add_file
                                        from
                                           (
                                              select
                                                 log_stream.add_file    
                                              from `
                                                 + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.trg_mktg_activity_plr_delta_log_insert_stream log_stream 
                                              where log_stream.add_file is not null 
                                                  and not exists (
                                                                  select 
                                                                     distinct filename 
                                                                  from `
                                                                     + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."trg_mktg_activity_plr" target 
                                                                  where 
                                                                      target.filename = log_stream.add_file
                                                  ) 
                                            ) stream_add 
                                         where        
                                             stream_add.add_file = delta_stream.filename )`;

    var delete_json_data = `DELETE FROM ` + DST_DB_PARAM+`.`+DST_SCHEMA_PARAM+`."trg_mktg_activity_plr" target
                              WHERE filename in (
                                        SELECT
                                            remove_file
                                        FROM `
                                            + SRC_DB_PARAM+`.`+SRC_SCHEMA_PARAM+`.trg_mktg_activity_plr_delta_log
                                        WHERE
                                            remove_file IS NOT NULL
                            )`;
    try {
        snowflake.execute (
        {sqlText: "begin transaction"}
        );

        var insert_stream_data_stmt = snowflake.createStatement(
                {
                sqlText: insert_stream_data
                }
        );
        insert_stream_data_stmt.execute();
        var delete_json_data_stmt = snowflake.createStatement(
                {
                sqlText: delete_json_data
                }
        );
        delete_json_data_stmt.execute();
        snowflake.execute (
            {sqlText: "commit"}
        );
        return "Succeeded.";
        }
    catch (err)  {
        snowflake.execute (
            {sqlText: "rollback"}
        );
        throw err;
        }
    ';
