                                                )
                                          )
                                          metadata
                                       where
                                          metadata.add_file = delta_table.filename )`;

    var delete_json_data = `DELETE FROM `+ DST_DB_PARAM +`.`+DST_SCHEMA_PARAM+`."trg_mktg_member_plr" target
                              WHERE filename in (
