CREATE TASK IF NOT EXISTS CUST_ADDRESS_PLR_DELTA_TASK
	warehouse=RA_UA_WH
	schedule='1 minute'
	when system$stream_has_data('STG_DEV.CDMSYNC.cust_address_plr_stream')
	as BEGIN
    ALTER EXTERNAL TABLE IF EXISTS STG_DEV.CDMSYNC.cust_address_plr_delta REFRESH;
    INSERT INTO STG_DEV.CDMSYNC.cdm_sync_stream_commit
        SELECT
            'cust_address_plr_delta_task',
            relative_path,
            size,
            last_modified
        FROM
            STG_DEV.CDMSYNC.cust_address_plr_stream;
END;
