CREATE PROCEDURE IF NOT EXISTS "COMPARE_TABLES_WITH_PRIMARY_KEY"("DB1" VARCHAR(16777216), "SCHEMA1" VARCHAR(16777216), "TABLE1" VARCHAR(16777216), "DB2" VARCHAR(16777216), "SCHEMA2" VARCHAR(16777216), "TABLE2" VARCHAR(16777216), "PRIMARY_KEY" VARCHAR(16777216))
RETURNS VARIANT
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
// Parse the database, schema, and table names from the input parameters
const db1 = DB1.toUpperCase();
const schema1 = SCHEMA1.toUpperCase();
const table1 = TABLE1.toUpperCase();
const db2 = DB2.toUpperCase();
const schema2 = SCHEMA2.toUpperCase();
const table2 = TABLE2.toUpperCase();
const primary_key = PRIMARY_KEY.toUpperCase();
// Create a temporary table to store mismatch results
const tempTableName = ''mismatch_results_'' + table1 + ''_'' + table2;
const createTableQuery = `
  CREATE or replace TEMPORARY TABLE ${tempTableName} (
      PRIMARY_KEY_VALUE VARCHAR,
      COLUMN_NAME VARCHAR,
      ${table1}_1 varchar,
      ${table2}_2 varchar
  )
`;
snowflake.createStatement({ sqlText: createTableQuery }).execute();
// Get the list of column names from both tables
const columnsQuery = `
SELECT COLUMN_NAME || t1 AS COLUMN_NAME, ${table1} AS TABLE_ALIAS
FROM ${db1}.INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_NAME = :3 AND TABLE_SCHEMA = :2
UNION ALL
SELECT COLUMN_NAME || t2 AS COLUMN_NAME, ${table2} AS TABLE_ALIAS
FROM ${db2}.INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_NAME = :6 AND TABLE_SCHEMA = :5
`;
const stmt = snowflake.createStatement({
  sqlText: columnsQuery,
  binds: [table1, schema1, table2, schema2]
});
const columnsResult = stmt.execute();
// Loop through each column
while (columnsResult.next()) {
  const columnName = columnsResult.getColumnValue(1);
  const tableAlias = columnsResult.getColumnValue(2);
  // Compare values between tables based on a common identifier
  const comparisonQuery = `
      INSERT INTO ${tempTableName}
      SELECT t1.${primary_key}, ${columnName}, t1.${columnName}, t2.${columnName}
      FROM ${db1}.${schema1}.${table1} t1
      JOIN ${db2}.${schema2}.${table2} t2 ON t1.${primary_key} = t2.${primary_key}
      WHERE t1.${columnName} IS NULL OR t2.${columnName} IS NULL OR t1.${columnName} != t2.${columnName}
  `;
  snowflake.createStatement({ sqlText: comparisonQuery }).execute();
}
// Return the name of the temporary table
return tempTableName;
';
CREATE PROCEDURE IF NOT EXISTS "COMPARE_TABLES_WITH_PRIMARY_KEY"("TABLE1" VARCHAR(16777216), "TABLE2" VARCHAR(16777216), "PRIMARY_KEY" VARCHAR(16777216))
RETURNS VARIANT
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
// Parse the database, schema, and table names from the input parameters
const [db1, schema1, table1] = TABLE1.split(".");
const [db2, schema2, table2] = TABLE2.split(".");
const primary_key = PRIMARY_KEY;
// Create a temporary table to store mismatch results
const tempTableName = ''mismatch_results_'' + table1 + ''_'' + table2;
const createTableQuery = `
   CREATE or replace TEMPORARY TABLE ${tempTableName} (
       PRIMARY_KEY_VALUE VARCHAR,
       COLUMN_NAME VARCHAR,
       ${table1}_1 varchar,
       ${table2}_2 varchar
   )
`;
snowflake.createStatement({ sqlText: createTableQuery }).execute();
// Get the list of column names from both tables
    const columnsQuery = `
 SELECT COLUMN_NAME
 FROM ${db1}.INFORMATION_SCHEMA.COLUMNS
 WHERE TABLE_NAME IN ${table1}
`;

const columnsResult = snowflake.createStatement({ sqlText: columnsQuery }).execute();

// Loop through each column
while (columnsResult.next()) {
   const columnName = columnsResult.getColumnValue(1);
   // Compare values between tables based on a common identifier
   const comparisonQuery = `
       INSERT INTO ${tempTableName}
       SELECT t1.${primary_key}, ${columnName}, t1.${columnName}, t2.${columnName}
       FROM ${db1}.${schema1}.${table1} t1
       JOIN ${db2}.${schema2}.${table2} t2 ON t1.${primary_key} = t2.${primary_key}
       WHERE t1.${columnName} IS NULL OR t2.${columnName} IS NULL OR t1.${columnName} != t2.${columnName}
   `;
   snowflake.createStatement({ sqlText: comparisonQuery }).execute();
}
// Return the name of the temporary table
return tempTableName;
';
CREATE PROCEDURE IF NOT EXISTS "COMPARE_TABLES_WITH_PRIMARY_KEY_TEST"("TABLE1" VARCHAR(16777216), "TABLE2" VARCHAR(16777216), "PRIMARY_KEY" VARCHAR(16777216))
RETURNS VARIANT
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
var table1 = TABLE1;
var table2 = TABLE2;
var primary_key = PRIMARY_KEY;

var tempTableName = ''mismatch_results_'' + table1 + ''_'' + table1;
var createTableQuery = "
 CREATE or replace TEMPORARY TABLE ${tempTableName} (
   PRIMARY_KEY_VALUE VARCHAR(16777216),
   COLUMN_NAME VARCHAR(16777216),
   table1 VARCHAR(16777216),
   table2 VARCHAR(16777216))";

snowflake.execute( {sqlText: createTableQuery} );

var columnsQuery = "
 SELECT COLUMN_NAME
 FROM INFORMATION_SCHEMA.COLUMNS
 WHERE TABLE_NAME IN (:1, :2)
";
var columnsResult = snowflake.execute( {sqlText: createTableQuery,binds: [table1, table2]} );

while (columnsResult.next()) {
 var columnName = columnsResult.getColumnValue(1);

 var comparisonQuery = `
   INSERT INTO ${tempTableName}
   SELECT ${table1}.${primary_key},${columnName},${table1}.${columnName}, ${table2}.${columnName}
   FROM ${table1}
    JOIN ${table2} ON ${table1}.${primary_key} = ${table2}.${primary_key}
   WHERE ${table1}.${columnName} IS NULL OR ${table2}.${columnName} IS NULL OR ${table1}.${columnName} != ${table2}.${columnName}
 `;
 snowflake.execute({ sqlText: comparisonQuery });
}

return tempTableName;
';
CREATE PROCEDURE IF NOT EXISTS "GETQUERYTEXT"("TABLE_NAME" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
    var row_count = 0;
    // Dynamically compose the SQL statement to execute.
    var sqlCommand = "select count(*) from " + TABLE_NAME;
    // Prepare statement.
    var stmt = snowflake.createStatement({sqlText: sqlCommand});
	var rs = stmt.execute()
	// get SQL text from Statement
	var queryText = stmt.getSqlText();
    return queryText;
    ';
