CREATE VIEW IF NOT EXISTS COREDIM_LOYALTY_MBR_OFFER_V(
	BRAND_ID,
	CDM_LOAD_DT,
	CREATE_DTTM,
	EXPIRATION_DTTM,
	LOAD_DTTM,
