           'ecosure' as SOURCE_SYSTEM_NAME,
           AUDITID                                      AS AUDITID,
           NULLIF(TRIM(SECTIONNUM), '')                 AS SECTIONNUM,
           NULLIF(TRIM(SECTIONNAME), '')                AS SECTIONNAME,
