    BC.LAST_NAME AS LAST_NM,
    BC.MIDDLE_NAME AS MIDDLE_INITIAL_TXT,
    BC.DATE_OF_BIRTH AS DOB_DT,
    BC.BIRTH_MONTH AS BIRTH_MNTH_ID,
    BC.BIRTH_YR AS BIRTH_YEAR_ID,
    BC.BIRTH_IMPLIED_IND AS BIRTH_DT_IMPLIED_IND,
