CREATE FUNCTION IF NOT EXISTS "EXTACT_STORE_ID"("STORE_NAME" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE PYTHON
RUNTIME_VERSION = '3.8'
HANDLER = 'extact_store_id'
AS '
import re
regex = r''#(\\d*)$''
def extact_store_id(store_name):
    match = re.search(regex, store_name)
    if match:
        return match.group(1)
    return None
';
CREATE FUNCTION IF NOT EXISTS "EXTRACT_STORE_ID_PDQ"("NAME" VARCHAR(16777216))
RETURNS VARCHAR(16777216)
LANGUAGE PYTHON
RUNTIME_VERSION = '3.8'
HANDLER = 'extract_storenumber'
AS '
import re
def extract_storenumber(storename):
    match_opt = re.search(''(.*)(#)(.*)'', storename.replace('' '', ''''))
    if not match_opt:
        return None

    match = match_opt.group(3)
    s_num = match.zfill(4)
    if len(s_num) == 4:
        return s_num
    elif s_num[0] == "9":
        return s_num[0] + s_num[2:]
    else:
        return None
';
