        return None
';
CREATE FUNCTION IF NOT EXISTS "FLAT_GA_EVENTS_UP_EP_VALUE"("A" ARRAY)
RETURNS ARRAY
LANGUAGE JAVASCRIPT
AS '
    const FLEXIBLE_KEY_NAMES = ["string_value", "int_value", "double_value", "float_value"]

    const parseInput = (input = {}) => {
        const res = {
            "key": input.key
        };
        const value = input.value;
        if (value) {
            for (const [key, value] of Object.entries(input.value)) {
                if (FLEXIBLE_KEY_NAMES.includes(key)) {
                    res.value = value;
                } else {
                    res[key] = value;
                }
            }
        }
        return res;
    }

    return A.map(parseInput)
  ';
CREATE PROCEDURE IF NOT EXISTS "GET_STAGE_SMALL_FILES_METADATA"("STAGE_NAME" VARCHAR(16777216), "PATTERN" VARCHAR(16777216), "MAX_SIZE" NUMBER(38,0), "DEST_ERROR_TABLE" VARCHAR(16777216))
RETURNS TABLE ("NAME" VARCHAR(16777216), "SIZE" NUMBER(38,0))
LANGUAGE PYTHON
RUNTIME_VERSION = '3.8'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'get_stage_small_files_metadata'
EXECUTE AS OWNER
AS '
from snowflake.snowpark.functions import col,lit

def get_stage_small_files_metadata(session, stage_name, pattern,max_size,dest_error_table):
   return session.sql(f"LIST @{stage_name} pattern=''{pattern}''").where(col(''size'')<=lit(max_size)).select(col(''name''),col(''size''))
   
';
CREATE FUNCTION IF NOT EXISTS "KV_ARRAY_TO_OBJECT"("A" ARRAY)
RETURNS OBJECT
LANGUAGE JAVASCRIPT
AS '
    let dict = {};
    A.forEach(item => {
        dict[item.key] = item.value;
    });
    return dict;
';
